CREATE OR REPLACE FUNCTION public.register_verified_profile(p_full_name text, p_city text DEFAULT 'თბილისი'::text, p_district text DEFAULT NULL::text, p_neighborhood text DEFAULT NULL::text, p_account_types text[] DEFAULT ARRAY['user'::text], p_other_service text DEFAULT ''::text, p_specialist_profile jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_phone text := public.current_verified_phone();
  v_id uuid;
  v_types text[] := coalesce(p_account_types,array['user']::text[]);
  v_primary_type text;
begin
  if v_uid is null or length(coalesce(v_phone,'')) <> 9 then
    return jsonb_build_object('ok',false,'code','otp_required','message','ტელეფონის SMS დადასტურება აუცილებელია.');
  end if;
  if coalesce(trim(p_full_name),'')='' then
    return jsonb_build_object('ok',false,'code','invalid_name','message','სახელი აუცილებელია.');
  end if;
  if exists(select 1 from public.profiles p where p.phone=v_phone) then
    return jsonb_build_object('ok',false,'code','phone_exists','message','ეს ნომერი უკვე რეგისტრირებულია.');
  end if;
  if exists(select 1 from public.profiles p where p.auth_user_id=v_uid) then
    return jsonb_build_object('ok',false,'code','auth_user_exists','message','ამ ავტორიზაციაზე პროფილი უკვე არსებობს.');
  end if;

  v_primary_type := case when 'user'=any(v_types) then 'user' else coalesce(v_types[1],'user') end;
  insert into public.profiles(
    phone,full_name,city,district,neighborhood,account_type,is_super_admin,
    account_types,other_service,specialist_profile,auth_user_id,phone_verified_at
  ) values(
    v_phone,trim(p_full_name),nullif(trim(coalesce(p_city,'')),''),p_district,p_neighborhood,
    v_primary_type,false,v_types,coalesce(p_other_service,''),p_specialist_profile,v_uid,now()
  ) returning id into v_id;

  return jsonb_build_object('ok',true,'id',v_id,'phone',v_phone,'verified',true);
exception
  when unique_violation then
    return jsonb_build_object('ok',false,'code','phone_exists','message','ეს ნომერი უკვე რეგისტრირებულია.');
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_live_chat_member(p_phone text, p_chat_id uuid, p_member_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text:=regexp_replace(coalesce(p_phone,''),'\D','','g');v_member text:=regexp_replace(coalesce(p_member_phone,''),'\D','','g');v_myrole text;v_targetrole text;
begin
 select role into v_myrole from public.live_chat_members where chat_id=p_chat_id and phone=v_phone;
